/**
 * Code block diff helpers.
 *
 * Finds the "previous version" of a code block by matching it against
 * code blocks extracted from earlier messages of the same chat.
 *
 * Matching priority:
 *   1. Exact file path match            (strongest)
 *   2. Same file name, different folder (plus content similarity)
 *   3. Same language + high line similarity (covers blocks without a path)
 */

const SIMILARITY_THRESHOLD = 0.35
const MIN_SCORE = 30

/**
 * Normalize path separators and trim. Returns '' when there is no path.
 */
export function normalizeBlockPath(path) {
  if (!path) return ''
  return path.replace(/\\/g, '/').trim()
}

/**
 * Last segment of a file path (file name), or '' when there is no path.
 */
export function blockBaseName(path) {
  const normalized = normalizeBlockPath(path)
  if (!normalized) return ''
  return normalized.split('/').filter(Boolean).pop() || ''
}

/**
 * Jaccard similarity over normalized, non-empty lines.
 * Robust to re-ordering and small edits.
 */
export function contentSimilarity(a, b) {
  const toLineSet = text =>
    new Set((text || '').split('\n').map(line => line.trim()).filter(Boolean))

  const linesA = toLineSet(a)
  const linesB = toLineSet(b)
  if (!linesA.size || !linesB.size) return 0

  let intersection = 0
  for (const line of linesA) {
    if (linesB.has(line)) intersection++
  }
  const union = linesA.size + linesB.size - intersection
  return union === 0 ? 0 : intersection / union
}

/**
 * Score how likely `candidate` is a previous version of `current`.
 * Higher score = more likely. Returns { score, matchType }.
 */
export function scoreBlockMatch(current, candidate) {
  const currentPath = normalizeBlockPath(current?.filePath)
  const candidatePath = normalizeBlockPath(candidate?.filePath)
  const currentBase = blockBaseName(current?.filePath)
  const candidateBase = blockBaseName(candidate?.filePath)

  const sameLanguage =
    !!current?.language && current.language === candidate?.language

  // 1. Exact file path match
  if (currentPath && candidatePath && currentPath === candidatePath) {
    return { score: 1000, matchType: 'path' }
  }

  // 2. Same file name in a different folder
  if (currentPath && candidatePath && currentBase && currentBase === candidateBase) {
    const similarity = contentSimilarity(current.content, candidate.content)
    return { score: 500 + similarity * 100, matchType: 'filename' }
  }

  // 3. Language + content similarity (handles blocks without paths)
  const similarity = contentSimilarity(current?.content, candidate?.content)
  let score = similarity * 100
  if (sameLanguage) score += 15
  if (similarity >= SIMILARITY_THRESHOLD) score += 25
  return { score, matchType: similarity >= SIMILARITY_THRESHOLD ? 'content' : 'none' }
}

/**
 * Returns the most recent previous version of `currentBlock`.
 * `previousBlocks` MUST be ordered from newest to oldest.
 *
 * @returns {null|{ block: Object, score: number, matchType: string }}
 */
export function findPreviousBlockVersion(currentBlock, previousBlocks) {
  if (!currentBlock || !previousBlocks?.length) return null

  let best = null
  let bestScore = 0
  let bestType = 'none'

  for (const candidate of previousBlocks) {
    const { score, matchType } = scoreBlockMatch(currentBlock, candidate)
    // Strict ">" so equal scores keep the newest (first visited) candidate
    if (score > bestScore) {
      bestScore = score
      best = candidate
      bestType = matchType
    }
  }

  if (!best || bestType === 'none' || bestScore < MIN_SCORE) return null

  return { block: best, score: bestScore, matchType: bestType }
}

/**
 * Extracts code blocks with file paths from markdown content
 * Pattern: ```lang /path/to/file
 */
export function extractCodeBlocks(content) {
  if (!content || typeof content !== 'string') return []

  const codeBlocks = []
  const lines = content.split('\n')
  let i = 0

  while (i < lines.length) {
    const line = lines[i]
    const match = line.match(/^```(\w+)\s+(.+)$/)

    if (match) {
      const language = match[1]
      const filePath = match[2].trim()

      // Only include blocks with file paths
      if (filePath) {
        const blockContent = []
        i++

        // Collect lines until closing ```
        while (i < lines.length && lines[i] !== '```') {
          blockContent.push(lines[i])
          i++
        }

        codeBlocks.push({
          language,
          filePath,
          content: blockContent.join('\n'),
          fileName: filePath.split('/').pop()
        })
      }
    }
    i++
  }

  return codeBlocks
}

/**
 * Extracts ALL fenced code blocks (with or without a file path).
 * Pattern: ```lang [optional/file/path]
 *
 * Unlike extractCodeBlocks, blocks without a path are included so they can
 * still be diffed against previous versions across messages.
 */
export function extractAllCodeBlocks(content) {
  if (!content || typeof content !== 'string') return []

  const codeBlocks = []
  const lines = content.split('\n')
  let i = 0

  while (i < lines.length) {
    const match = lines[i].match(/^```(\w+)\s*(.*)$/)

    if (match) {
      const language = match[1]
      const filePath = (match[2] || '').trim()
      const blockContent = []

      i++
      while (i < lines.length && lines[i] !== '```') {
        blockContent.push(lines[i])
        i++
      }

      const body = blockContent.join('\n')
      if (body.trim()) {
        codeBlocks.push({
          language,
          filePath,
          content: body,
          fileName: filePath ? filePath.split('/').pop() : ''
        })
      }
    }
    i++
  }

  return codeBlocks
}

/**
 * Checks if content has extractable code blocks with file paths
 */
export function hasCodeBlocksWithPaths(content) {
  return extractCodeBlocks(content).length > 0
}

// ── ADD INSIDE ChatService (e.g. next to extractCodeBlocksFromMessage) ──

/**
 * Flattens all code blocks found in the given messages.
 * Ordered from the NEWEST message to the OLDEST, so the first match found
 * by findPreviousBlockVersion is the most recent previous version.
 * Each block is tagged with its source message index/id.
 */
collectCodeBlocksFromMessages(messages) {
  const blocks = []
  const list = messages || []

  for (let i = list.length - 1; i >= 0; i--) {
    const message = list[i]
    extractAllCodeBlocks(message?.content || '').forEach((block, blockIndex) => {
      blocks.push({
        ...block,
        messageId: message.doc_id || message.id,
        messageIndex: i,
        blockIndex
      })
    })
  }

  return blocks
}

extractCodeBlocksFromMessage(message) {
  return extractCodeBlocks(message?.content || '')
}

effectiveCode() {
  return this.localCode !== null ? this.localCode : this.code
},

/**
 * True when this block has a matched previous version AND that version
 * actually differs from the current content.
 */
hasReference() {
  return !!this.referenceContent && this.referenceContent !== this.effectiveCode
},

/**
 * The "old" side of the diff.
 * - reference diff  -> the previous message's block
 * - file diff       -> the file currently on disk
 */
comparisonBase() {
  return this.showReferenceDiff ? this.referenceContent : this.orgContent
},

toggleView() {
  if (this.hasDiffEdits) {
    this.pendingViewSwitch = 'toggle'
    this.showConfirmModal = true
  } else if (this.showReferenceDiff) {
    // Leaving reference diff returns to plain code view
    this.showReferenceDiff = false
    this.showDiff = false
  } else {
    this.showDiff = !this.showDiff
  }
},

/**
 * Toggles diffing the current block against its previous version
 * (from earlier messages) instead of against the file on disk.
 */
toggleReferenceDiff() {
  const enabling = !this.showReferenceDiff
  this.showReferenceDiff = enabling
  this.editMode = false
  this.showDiff = enabling
},

